// 报价与手记绑定同一世界来源；任何读页都不自动递交、返报或选择外交答复。
#include "envoy_task_view.hpp"
#include <algorithm>
namespace hanmo::resident {
Outcome<EnvoyTaskProgress> query_envoy_task_progress(const CommonStore& common,const TaskState& tasks,const EnvoyTaskState& envoy,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const StableId& id,const DiplomaticEnvoyReportRead* reports){
    const auto& observer=common.state().metadata.player_actor_id;const auto* task=tasks.tasks.find(id);if(!task||task->assignee!=observer)return {false,{},common_failure("TaskNotKnown").error};EnvoyTaskRead read=reports?EnvoyTaskRead(common,tasks,envoy,missions,presentations,*reports):EnvoyTaskRead(common,tasks,envoy,missions,presentations);auto source=read.envoy_task_source(id);if(!source.ok)return {false,{},source.error};const auto* contract=envoy.envoy_contracts.find(id);const auto& a=source.value.acceptance;
    if(contract->pending_code.size()>4096)return {false,{},common_failure("EnvoyTaskTextLimit").error};EnvoyTaskProgress result;result.source_identity=common.state().identity;result.observer_actor_id=observer;result.task_id=id;result.mission_authority_fact_id=a.mission_authority_fact_id;result.acceptance_fact_id=a.fact_id;result.contract_id=a.contract_id;result.display_name=a.display_name;result.status=task->status;result.waiting_code=contract->pending_code;result.delivery_site_id=a.delivery_site_id;result.report_site_id=a.report_site_id;result.accepted_tick=a.accepted_tick;result.delivery_expires_tick=a.delivery_expires_tick;result.return_report_required=a.return_report_required;
    if(contract->action){const auto& link=*contract->action;const auto* action=common.action(link.action_id);const auto* actor=common.actor(observer);const auto expected=link.kind==EnvoyTaskActionKind::deliver?"envoy_deliver":"envoy_report";
        const auto* provider=common.actor(link.context.provider_actor_id);const auto& site=link.kind==EnvoyTaskActionKind::deliver?a.delivery_site_id:a.report_site_id;
        if(source.value.completion||(link.kind!=EnvoyTaskActionKind::deliver&&link.kind!=EnvoyTaskActionKind::report)||!action||action->kind!=expected||action->actor_id!=observer||action->remaining_ticks<1||action->start_tick>common.tick()||!actor||actor->action_id!=link.action_id||!provider||provider->id==observer||provider->action_id!=link.action_id||link.context.place_id!=site||action->participants.size()!=2||std::count(action->participants.begin(),action->participants.end(),observer)!=1||std::count(action->participants.begin(),action->participants.end(),provider->id)!=1||(link.kind==EnvoyTaskActionKind::deliver?bool(source.value.delivery):!source.value.delivery))return {false,{},common_failure("InvalidEnvoyVisibleAction",id,ErrorKind::internal).error};result.action_id=action->id;result.action_kind=expected;result.remaining_ticks=action->remaining_ticks;
    }
    if(source.value.delivery){if(source.value.delivery->completed_tick>common.tick())return {false,{},common_failure("EnvoyViewBeforeClockCommit",id,ErrorKind::internal).error};result.delivery_fact_id=source.value.delivery->fact_id;result.delivered_tick=source.value.delivery->completed_tick;}
    if(source.value.completion){if(source.value.completion->completed_tick>common.tick())return {false,{},common_failure("EnvoyViewBeforeClockCommit",id,ErrorKind::internal).error};result.final_fact_id=source.value.completion->fact_id;result.final_reason=source.value.completion->reason;result.completed_tick=source.value.completion->completed_tick;result.diplomatic_report_fact_id=source.value.completion->diplomatic_report_fact_id;}
    if(!contract->interruptions.empty()){const auto& stop=contract->interruptions.back();const auto* fact=common.state().facts.find(stop.fact_id);if(!fact||fact->kind!="envoy_handover_interrupted"||fact->domain!="tasks"||stop.task_id!=id||stop.contract_id!=a.contract_id||stop.acceptance_fact_id!=a.fact_id||stop.started_tick<a.accepted_tick||stop.stopped_tick<stop.started_tick||stop.stopped_tick>common.tick()||stop.completed_work_ticks<0||stop.completed_work_ticks>stop.stopped_tick-stop.started_tick)return {false,{},common_failure("InvalidEnvoyVisibleInterruption",id,ErrorKind::internal).error};result.last_interruption_fact_id=stop.fact_id;result.last_interruption_reason=stop.reason;result.last_interruption_tick=stop.stopped_tick;result.last_completed_work_ticks=stop.completed_work_ticks;}
    return {true,std::move(result),{}};
}
// 明确delivery_completion的exclusive边界；返报没有另造截止tick，不能借它延长原递交窗口。
BoundaryValue encode_envoy_task_progress(const EnvoyTaskProgress& r){using V=BoundaryValue;StableId hex;const char* digits="0123456789abcdef";for(const auto byte:r.source_identity.world_id){hex.push_back(digits[byte>>4]);hex.push_back(digits[byte&15]);}V identity=boundary::obj({{"world_id",V{hex}},{"execution_epoch",V{r.source_identity.execution_epoch}},{"revision",V{r.source_identity.revision}},{"tick",V{r.source_identity.tick}}});V::Dict result{{"ok",V{true}},{"source_identity",std::move(identity)},{"observer_actor_id",V{r.observer_actor_id}},{"task_id",V{r.task_id}},{"mission_authority_fact_id",V{r.mission_authority_fact_id}},{"acceptance_fact_id",V{r.acceptance_fact_id}},{"contract_id",V{r.contract_id}},{"final_reason",V{r.final_reason}},{"display_name",V{r.display_name}},{"status",V{r.status}},{"waiting_code",V{r.waiting_code}},{"delivery_site_id",V{r.delivery_site_id}},{"report_site_id",V{r.report_site_id}},{"accepted_tick",V{r.accepted_tick}},{"delivery_expires_tick",V{r.delivery_expires_tick}},{"deadline_scope",V{StableId{"delivery_completion"}}},{"deadline_inclusive",V{false}},{"return_report_required",V{r.return_report_required}}};if(r.action_id)result.emplace_back("action_id",V{*r.action_id});if(r.action_kind)result.emplace_back("action_kind",V{*r.action_kind});if(r.remaining_ticks)result.emplace_back("remaining_ticks",V{*r.remaining_ticks});if(r.delivery_fact_id)result.emplace_back("delivery_fact_id",V{*r.delivery_fact_id});if(r.delivered_tick)result.emplace_back("delivered_tick",V{*r.delivered_tick});if(r.diplomatic_report_fact_id)result.emplace_back("diplomatic_report_fact_id",V{*r.diplomatic_report_fact_id});if(r.final_fact_id)result.emplace_back("final_fact_id",V{*r.final_fact_id});if(r.completed_tick)result.emplace_back("completed_tick",V{*r.completed_tick});if(r.last_interruption_fact_id)result.emplace_back("last_interruption_fact_id",V{*r.last_interruption_fact_id});if(r.last_interruption_reason)result.emplace_back("last_interruption_reason",V{*r.last_interruption_reason});if(r.last_interruption_tick)result.emplace_back("last_interruption_tick",V{*r.last_interruption_tick});if(r.last_completed_work_ticks)result.emplace_back("last_completed_work_ticks",V{*r.last_completed_work_ticks});return V{std::move(result)};}
// 根据真正任务阶段叙述，始终把使者职责完成与政治认可分开。
std::vector<StableId> envoy_task_progress_lines(const EnvoyTaskProgress& r){
    const auto state=r.status=="active"?(r.action_id?(r.waiting_code.empty()?"正在当面递交":"交接暂缓"):"尚待当面递交"):r.status=="ready"?(r.action_id?(r.waiting_code.empty()?"正在返报":"返报暂缓"):"已递交，尚待本人返报"):r.status=="success"?"已按委任办结":r.status=="cancelled"?"已取消":"未能办妥";std::vector<StableId> lines{r.display_name+" · "+state};
    if(!r.delivery_fact_id&&(r.status=="active"||r.status=="ready")){if(r.source_identity.tick>=r.delivery_expires_tick)lines.push_back("递交期限已过，尚无有效呈递记录。");else lines.push_back("须在 "+std::to_string(r.delivery_expires_tick-r.source_identity.tick)+" 个半日的边界到来之前完成递交，不含该边界。");}
    if(!r.waiting_code.empty())lines.push_back(r.waiting_code=="BattlePending"?"当前战事尚未处理，交接暂缓。":(r.waiting_code=="EnvoyUnavailable"||r.waiting_code=="Unavailable"||r.waiting_code=="DiplomaticEnvoyUnavailable")?"本人暂时不能继续交接，原进度保留。":(r.waiting_code=="EnvoyContactRenewalRequired"||r.waiting_code=="EnvoyReportContactRenewalRequired"||r.waiting_code=="DiplomaticReportReceiverChanged"||r.waiting_code=="DiplomaticReportReceiverUnauthorized"||r.waiting_code=="DiplomaticReportContactChanged"||r.waiting_code=="EnvoyContactUnavailable"||r.waiting_code=="EnvoyReportContactUnavailable"||r.waiting_code=="EnvoyReportRoleChanged"||r.waiting_code=="EnvoyRoleChanged"||r.waiting_code=="DiplomaticRepresentativeChanged"||r.waiting_code=="DiplomaticRepresentativeUnauthorized")?"原会面已不能继续，需要重新接触合法接收代表。":"委任权责发生变化，现有责任保留，等待核实处理。");
    if(r.last_completed_work_ticks)lines.push_back("上次中止的交接已做 "+std::to_string(*r.last_completed_work_ticks)+" 个半日；该次交接未办结。");
    if(r.final_reason=="DeliveryExpired")lines.push_back("未在原定期限内完成递交。");else if(r.final_reason=="EnvoyDead")lines.push_back("使者死亡，未完责任已终止，原历史保留。");else if(r.final_reason=="PrincipalDissolved")lines.push_back("责任主体已经解散，未完责任已终止，原历史保留。");
    if(r.remaining_ticks)lines.push_back("本次当面交接还需 "+std::to_string(*r.remaining_ticks)+" 个半日。");if(r.return_report_required&&!r.final_fact_id)lines.push_back("原委任要求回到约定的发令场所返报。");if(r.delivery_fact_id)lines.push_back("提议已有实际呈递记录；对方是否认可，仍以其明确答复为准。");if(r.diplomatic_report_fact_id)lines.push_back("已向原委任机关的合法接收人当面返报，报告来源已留存。");if(r.status=="cancelled"&&r.delivery_fact_id)lines.push_back("取消使者任务不会撤回已经递交的提议。");return lines;
}
}
